// shared state between rows (one booking / hold is reused by several rows, exactly like a tester would)
const S = {};
async function booked(types = ['ADT']) {
  if (S.booked) return S.booked;
  const v = await chainTo('addpax', types, { fresh: true, seed: 5 }); if (!v.ok) return (S.booked = { err: v.why, v });
  const ctx = v.ctx; const b = await C.bookLike(ctx, 'book', v.ids.id, v.ids.off, {}); S.bookReq = { id: v.ids.id, off: v.ids.off };
  if (!ok(b)) return (S.booked = { err: 'Book: ' + errLine(b), v, b });
  return (S.booked = { v, b, bk: { pnr: b.json.pnr, gdsPNR: b.json.gdsPNR, bookingToken: b.json.bookingToken }, ctx });
}
async function held(types = ['ADT']) {
  if (S.held) return S.held;
  const v = await chainTo('addpax', types, { fresh: true, seed: 6 }); if (!v.ok) return (S.held = { err: v.why, v });
  const h = await C.bookLike(v.ctx, 'hold', v.ids.id, v.ids.off, {});
  if (!ok(h)) return (S.held = { err: 'Hold: ' + errLine(h), v, h });
  return (S.held = { v, h, bk: { pnr: h.json.pnr, gdsPNR: h.json.gdsPNR, bookingToken: h.json.bookingToken }, ctx: v.ctx });
}
const needFlags = o => ({ haveBundles: o.haveBundles, canBeHeld: o.canBeHeld, offerHasAncillary: o.offerHasAncillary, offerHasSeat: o.offerHasSeat, isSeatMapRequired: o.isSeatMapRequired, isAncillaryRequired: o.isAncillaryRequired, isBaggageRequired: o.isBaggageRequired, isMealRequired: o.isMealRequired });
const EXPKEYS = ['responseId', 'supplier', 'journeys', 'flightSegments', 'priceClasses', 'baggageDetails', 'offers'];
const OFFERKEYS = ['offerId', 'offerJourneys', 'passengerFareBreakdown', 'priceDetails', 'refundability', 'haveBundles', 'canBeHeld', 'isAncillaryRequired', 'offerHasAncillary', 'isBaggageRequired', 'isMealRequired', 'isSeatMapRequired'];

// ================= SEARCH =================
add('generic', 'TC-SEARCH-POS-01', async () => {
  const ctx = ctxNew('s'); const r = await X.sFind(ctx, [['COK', 'SHJ', D1]], ['ADT', 'ADT', 'CHD', 'INF'], { tries: 3, anyFit: true }); const h = r.h; const offers = (h.json && h.json.offers) || [];
  const miss = []; offers.forEach((o, i) => OFFERKEYS.forEach(k => { if (!(k in o)) miss.push(`offers[${i}].${k}`); }));
  const good = ok(h) && offers.length > 0 && !miss.length && !!h.json.responseId;
  return { verdict: good ? 'PASS' : 'FAIL', hops: [h], actual: ok(h) ? `HTTP 200, ${offers.length} offer(s), responseId ${h.json.responseId ? 'present' : 'MISSING'}, ${miss.length ? 'missing: ' + miss.join(',') : 'every offer carries offerId, priceDetails and the capability flags'}` : errLine(h), evidence: `route COK-SHJ ${D1}, 2 ADT + 1 CHD + 1 INF; flags offer[0]: ${JSON.stringify(needFlags(offers[0] || {}))}`, waiting_ms: ctx.waiting_ms };
}, { endpoint: 'Search' });
