add('generic', 'TC-SEARCH-VAL-01', async () => { const ctx = ctxNew('s'); const r = await X.sFind(ctx, [['COK', 'SHJ', D1]], ['ADT'], { tries: 3, anyFit: true }); const sup = r.resp && r.resp.supplier; return { verdict: sup === 'AirArabiaPlus' ? 'PASS' : 'FAIL', hops: [r.h], actual: `request supplier AirArabiaPlus, response supplier ${sup}`, evidence: 'credentialsSelector is not echoed by Search (checked: response keys ' + Object.keys(r.resp || {}).join(',') + ')', waiting_ms: ctx.waiting_ms }; }, { endpoint: 'Search' });
